import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { char[][] board = new char[3][3]; int xCount = 0, oCount = 0; for (int i = 0; i < 3; i++) { String line = br.readLine(); for (int j = 0; j < 3; j++) { board[i][j] = line.charAt(j); if (board[i][j] == 'X') xCount++; else if (board[i][j] == 'O') oCount++; } } boolean xWins = checkWin(board, 'X'); boolean oWins = checkWin(board, 'O'); if (!(xCount == oCount || xCount == oCount + 1) || (xWins && oWins) || (xWins && xCount == oCount) || (oWins && xCount > oCount)) { System.out.println(3); } else if (xWins || oWins || (xCount + oCount == 9)) { System.out.println(1); } else { System.out.println(2); } } } private static boolean checkWin(char[][] b, char p) { for (int i = 0; i < 3; i++) { if (b[i][0] == p && b[i][1] == p && b[i][2] == p) return true; if (b[0][i] == p && b[1][i] == p && b[2][i] == p) return true; } return (b[0][0] == p && b[1][1] == p && b[2][2] == p) || (b[0][2] == p && b[1][1] == p && b[2][0] == p); } }